const embedding = $json.embeddings?.[0];

if (!embedding) {
  throw new Error('Question embedding not found');
}

const question = $('Detect Simple Intent').first().json.question;
const queryVector = `[${embedding.join(',')}]`;

const searchQuery = `
SELECT 
  document_id,
  title,
  category,
  section_title,
  chunk_index,
  content,
  embedding <=> '${queryVector}'::vector AS distance
FROM document_chunks
ORDER BY embedding <=> '${queryVector}'::vector
LIMIT 2;
`;

return {
  json: {
    question,
    search_query: searchQuery
  }
};

const items = $input.all();

const question = $('Detect Simple Intent').first().json.question;

const usefulItems = items
  .filter((item) => {
    const content = item.json.content || '';

    const withoutHeadings = content
      .split('\n')
      .filter((line) => !line.trim().startsWith('#'))
      .join('\n')
      .trim();

    return withoutHeadings.length > 40;
  })
  .sort((a, b) => Number(a.json.distance) - Number(b.json.distance))
  .slice(0, 1);

const sources = usefulItems.map((item) => {
  const row = item.json;

  return {
    document_id: row.document_id,
    title: row.title,
    category: row.category,
    section_title: row.section_title,
    chunk_index: row.chunk_index
  };
});

const context = usefulItems.length
  ? usefulItems
      .map((item) => {
        const content = item.json.content || '';

        return content
          .split('\n')
          .filter((line) => !line.trim().startsWith('#'))
          .join('\n')
          .trim();
      })
      .join('\n\n')
  : 'NO_RELEVANT_SOURCE';

const prompt = `
You are an IT support assistant for İZELTAŞ.

Your task is to answer the user's question using ONLY the SOURCE TEXT.

Important rules:
- Answer in Turkish only.
- Use ONLY the SOURCE TEXT.
- Do not add information that is not in the source.
- Do not mention document names, document IDs, categories, chunks, sources, or metadata.
- Do not mention "source text" in the final answer.
- Write exactly 3 bullet points if there are enough relevant steps.
- If there are fewer than 3 relevant steps, write fewer bullet points.
- Never write 4 or more bullet points.
- Every bullet point must start with "- ".
- Each bullet point must be short, clear, and practical.
- Use natural Turkish.
- Use polite imperative language such as "kontrol edin", "emin olun", "deneyin", "başvurun".
- Do not start the answer with a random phrase such as "kontrol edin."
- Do not use broken Turkish.
- Do not use Chinese characters, English words, or mixed language.

If SOURCE TEXT is NO_RELEVANT_SOURCE, answer exactly:
- Bu konuda kaynak dokümanlarda yeterli bilgi bulamadım. IT destek ekibiyle iletişime geçebilirsiniz.

SOURCE TEXT:
${context}

USER QUESTION:
${question}

Final Turkish answer:
`;

return [
  {
    json: {
      question,
      context,
      prompt,
      sources
    }
  }
];

const buildPromptOutput = $('Build Prompt').first().json;

const question = buildPromptOutput.question;
const sources = buildPromptOutput.sources || [];

const rawAnswer = String(
  $json.text ||
  $json.output ||
  $json.response ||
  $json.answer ||
  $json.result ||
  $json.data?.text ||
  $json.data?.output ||
  ''
).trim();

if (!rawAnswer) {
  throw new Error('Model answer not found');
}

function fixCommonTurkishIssues(text) {
  return text
    .replace(/Kurulum tarafından/g, 'Kurum tarafından')
    .replace(/kurulum tarafından/g, 'kurum tarafından')
    .replace(/uyutmaya çalışın/g, 'uymaya çalışın')
    .replace(/uyutmaya/g, 'uymaya')
    .replace(/başvurulun/g, 'başvurun')
    .replace(/başvurulmalıdır/g, 'başvurulmalıdır')
    .replace(/kontrol edilin/g, 'kontrol edin')
    .replace(/Hesabiniz/g, 'Hesabınız')
    .replace(/hesabiniz/g, 'hesabınız')
    .replace(/kilideli/g, 'kilitli');
}

function normalizeBullets(answer) {
  let cleaned = fixCommonTurkishIssues(answer);

  const lines = cleaned
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);

  let bulletLines = lines.filter((line) => /^[-•]\s+/.test(line));

  if (bulletLines.length === 0) {
    const sentences = cleaned
      .split(/(?<=[.!?])\s+/)
      .map((sentence) => sentence.trim())
      .filter(Boolean);

    bulletLines = sentences.map((sentence) => `- ${sentence}`);
  }

  return bulletLines
    .slice(0, 3)
    .map((line) => {
      let text = line.replace(/^[-•]\s+/, '').trim();

      text = fixCommonTurkishIssues(text);

      if (!/[.!?]$/.test(text)) {
        text += '.';
      }

      return `- ${text}`;
    })
    .join('\n');
}

const answer = normalizeBullets(rawAnswer);

return {
  json: {
    question,
    answer,
    sources
  }
};

const body = $json.body || {};
const question = body.question || body.query || body.message;

if (!question || String(question).trim().length === 0) {
  throw new Error('Question is required. Send JSON body like: { "question": "..." }');
}

return {
  json: {
    question: String(question).trim()
  }
};

const input = $input.first().json;

const question = String(
  input.question || input.body?.question || ''
).trim();

if (!question) {
  throw new Error('Question is required.');
}

const normalized = question
  .toLocaleLowerCase('tr-TR')
  .replace(/[!?.,:;]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const greetingWords = [
  'merhaba',
  'selam',
  'selamlar',
  'iyi günler',
  'günaydın',
  'iyi akşamlar',
  'iyi çalışmalar'
];

const identityPatterns = [
  'sen kimsin',
  'kimsin',
  'nesin',
  'adın ne',
  'kendini tanıt',
  'kendini tanıtır mısın'
];

const capabilityPatterns = [
  'ne yapabiliyorsun',
  'neler yapabiliyorsun',
  'ne işe yarıyorsun',
  'hangi konularda yardımcı olabilirsin',
  'hangi konularda yardımcı oluyorsun',
  'bana nasıl yardımcı olabilirsin',
  'ne konuda yardımcı olabilirsin'
];

const thanksPatterns = [
  'teşekkürler',
  'teşekkür ederim',
  'sağ ol',
  'sağol',
  'eyvallah'
];

const supportedTopicKeywords = [
  'vpn',
  'şifre',
  'parola',
  'hesap',
  'kilit',
  'kilitlendi',
  'outlook',
  'mail',
  'e-posta',
  'eposta',
  'yazıcı',
  'printer',
  'çıktı',
  'toner',
  'donanım',
  'bilgisayar',
  'laptop',
  'ekran',
  'klavye',
  'mouse',
  'internet',
  'wifi',
  'wi-fi',
  'ağ',
  'bağlantı',
  'ekipman',
  'talep',
  'yetki',
  'yazılım',
  'program',
  'arıza',
  'hata',
  'yavaş'
];

function includesAny(patterns) {
  return patterns.some((pattern) => normalized.includes(pattern));
}

let staticAnswer = null;

if (greetingWords.includes(normalized)) {
  staticAnswer =
    'Merhaba, ben İZELTAŞ IT Danışma Asistanı’yım. VPN, şifre, Outlook, yazıcı, donanım, ağ bağlantısı ve ekipman talepleri gibi IT konularında yardımcı olabilirim.';
}

if (!staticAnswer && includesAny(identityPatterns)) {
  staticAnswer =
    'Ben İZELTAŞ IT Danışma Asistanı’yım. Lokal LLM ve RAG yapısıyla, yüklenen IT destek dokümanlarına göre kullanıcılara yardımcı olmak için tasarlandım.';
}

if (!staticAnswer && includesAny(capabilityPatterns)) {
  staticAnswer =
    'VPN bağlantısı, şifre işlemleri, Outlook sorunları, yazıcı problemleri, donanım destekleri, ağ bağlantısı ve ekipman talepleri hakkında yardımcı olabilirim.';
}

if (!staticAnswer && includesAny(thanksPatterns)) {
  staticAnswer =
    'Rica ederim. IT süreçleriyle ilgili başka bir konuda da yardımcı olabilirim.';
}

const isSupportedTopic = includesAny(supportedTopicKeywords);

const outOfScopeAnswer =
  'Bu konuda yardımcı olamam. Ben yalnızca VPN, şifre işlemleri, Outlook, yazıcı, donanım, ağ bağlantısı, yazılım yetkisi ve ekipman talepleri gibi IT destek konularında yardımcı olabilirim.';

return [
  {
    json: {
      question,
      is_static_response: Boolean(staticAnswer),
      is_supported_topic: Boolean(isSupportedTopic),
      answer: staticAnswer || outOfScopeAnswer,
      sources: []
    }
  }
];

const question = String($json.question || '').trim();
const answer = String($json.answer || '').trim();
const sources = Array.isArray($json.sources) ? $json.sources : [];

if (!question) {
  throw new Error('Question is required for chat log.');
}

if (!answer) {
  throw new Error('Answer is required for chat log.');
}

function sqlEscape(value) {
  return String(value ?? '').replace(/'/g, "''");
}

function maskSensitiveText(value) {
  return String(value ?? '')
    // E-mail maskeleme
    .replace(
      /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,
      '[masked_email]'
    )
    // Türkiye telefon numarası benzeri değerleri maskeleme
    .replace(
      /(\+90|0)?\s?5\d{2}\s?\d{3}\s?\d{2}\s?\d{2}/g,
      '[masked_phone]'
    )
    // Uzun numara dizilerini maskeleme
    .replace(
      /\b\d{8,}\b/g,
      '[masked_number]'
    );
}

const firstSource = sources[0] || {};

const category = firstSource.category || null;
const sectionTitle = firstSource.section_title || null;

const responseType = sources.length > 0 ? 'rag_answer' : 'static_or_out_of_scope';

const maskedQuestion = maskSensitiveText(question);
const maskedAnswer = maskSensitiveText(answer);
const sourcesJson = JSON.stringify(sources);

const insertQuery = `
INSERT INTO chat_logs (
  question,
  answer,
  sources,
  category,
  section_title,
  response_type
)
VALUES (
  '${sqlEscape(maskedQuestion)}',
  '${sqlEscape(maskedAnswer)}',
  '${sqlEscape(sourcesJson)}'::jsonb,
  ${category ? `'${sqlEscape(category)}'` : 'NULL'},
  ${sectionTitle ? `'${sqlEscape(sectionTitle)}'` : 'NULL'},
  '${sqlEscape(responseType)}'
)
RETURNING id, created_at;
`;

return {
  json: {
    question,
    answer,
    sources,
    category,
    section_title: sectionTitle,
    response_type: responseType,
    insert_query: insertQuery
  }
};

const chatData = $('Prepare Chat Log Insert').first().json;

return {
  json: {
    question: chatData.question,
    answer: chatData.answer,
    sources: chatData.sources || []
  }
};
